def vigenere_encrypt(plaintext, key):
    key = key.lower()
    key_index = 0
    ciphertext = ""
    for char in plaintext:
        if char.isalpha():
            shift = ord(key[key_index % len(key)]) - ord('a')
            offset = ord('A') if char.isupper() else ord('a')
            ciphertext += chr((ord(char) - offset + shift) % 26 + offset)
            key_index += 1
        else:
            ciphertext += char
    return ciphertext

